// Toyz Race — PWA plumbing: service worker registration, background updates, install prompt.
// The UI for it (install button, "ready offline" and "update ready" notices) is src/pwa/PwaLayer.jsx.
//
// Offline: the service worker (workbox, generated by vite-plugin-pwa) precaches EVERY file of the game on the
// first visit — before the app is even installed — so from then on the whole game except multiplayer runs with
// no network at all.
//
// Updates: while online the app looks for a new version at launch, every 30 minutes, when the connection comes
// back and when the player returns to the app. A new version downloads in the background and then waits; it is
// switched to (one quick reload) only when that cannot interrupt anything: right at launch, or while the app is
// in the background on a menu screen, or when the player taps "Restart" on the update notice.
//
// Service workers need a secure context: https:// or http://localhost. On plain http://192.168.x.x the game
// still runs online, but nothing here does anything.

const RELOAD_KEY = 'tt.pwa.updateReload';
const OFFLINE_SEEN_KEY = 'tt.pwa.offlineReadySeen';
const CHECK_EVERY_MS = 30 * 60 * 1000;
const CHECK_MIN_GAP_MS = 60 * 1000;
const LAUNCH_WINDOW_MS = 15000; // a waiting update is applied at launch only before the player touches anything

const hasWindow = () => typeof window !== 'undefined' && typeof document !== 'undefined';

// ---------------------------------------------------------------------------------------------------------------------
// Observable state for the React layer

/** @type {{ supported: boolean, offlineReady: boolean, updateReady: boolean, installable: boolean, installed: boolean }} */
let state = { supported: false, offlineReady: false, updateReady: false, installable: false, installed: false };
const listeners = new Set();
function setState(patch) {
  state = { ...state, ...patch };
  for (const l of [...listeners]) {
    try {
      l();
    } catch (err) {
      console.error(err);
    }
  }
}
export const pwaStore = {
  subscribe(l) {
    listeners.add(l);
    return () => listeners.delete(l);
  },
  get: () => state,
};

// ---------------------------------------------------------------------------------------------------------------------
// Install prompt

/** @type {any} the stashed `beforeinstallprompt` event (Chromium only) */
let deferredPrompt = null;

/** True when running as an installed app (home-screen icon / installed PWA window). */
export function isStandalone() {
  if (!hasWindow()) return false;
  try {
    if (window.matchMedia('(display-mode: standalone), (display-mode: fullscreen), (display-mode: minimal-ui)').matches) {
      // A browser tab that merely went fullscreen (stage.js requests it on phones) also matches display-mode: fullscreen.
      if (!document.fullscreenElement) return true;
    }
  } catch {}
  return navigator.standalone === true; // iOS Safari
}

/** iPhone / iPod / iPad (including iPadOS pretending to be a Mac). */
export function isIOS() {
  if (typeof navigator === 'undefined') return false;
  const ua = navigator.userAgent || '';
  if (/iPad|iPhone|iPod/.test(ua)) return true;
  return navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1;
}

/** True when an install button makes sense: native prompt available, or iOS where we can show instructions. */
export function canShowInstall() {
  if (state.installed || isStandalone()) return false;
  return !!deferredPrompt || (isIOS() && hasWindow() && window.isSecureContext !== false);
}

if (hasWindow()) {
  // Listen as soon as the module is evaluated: `beforeinstallprompt` can fire early.
  window.addEventListener('beforeinstallprompt', (e) => {
    e.preventDefault(); // keep the browser's own mini-infobar away; we show our own button
    deferredPrompt = e;
    setState({ installable: true });
  });
  window.addEventListener('appinstalled', () => {
    deferredPrompt = null;
    setState({ installable: false, installed: true });
  });
}

/**
 * Open the install flow. Must be called from a user gesture (click / tap).
 * Resolves with { outcome }: 'accepted' | 'dismissed' (native dialog shown), 'ios-instructions' (iOS: Share → Add to
 * Home Screen), 'installed' (already running as an app) or 'unavailable'.
 */
export async function promptInstall() {
  if (state.installed || isStandalone()) return { outcome: 'installed' };
  if (deferredPrompt) {
    const ev = deferredPrompt;
    deferredPrompt = null; // a prompt event can be used only once
    setState({ installable: false });
    try {
      await ev.prompt();
      const choice = await ev.userChoice;
      return { outcome: choice && choice.outcome === 'accepted' ? 'accepted' : 'dismissed' };
    } catch {
      return { outcome: 'unavailable' };
    }
  }
  if (isIOS()) return { outcome: 'ios-instructions' };
  return { outcome: 'unavailable' };
}

// ---------------------------------------------------------------------------------------------------------------------
// Service worker + updates

/** @type {((reload?: boolean) => Promise<void>) | null} */
let updateSW = null;
let initDone = false;

/** Switch to the downloaded version now (reloads the page). Returns false when there is nothing to apply. */
export function applyUpdate() {
  if (!state.updateReady || !updateSW) return false;
  try {
    sessionStorage.setItem(RELOAD_KEY, '1');
  } catch {}
  // Reload ourselves once the new worker controls the page. (The helper's own reload is skipped on a page that
  // was not controlled when it registered, i.e. during the very first visit.)
  let done = false;
  const reload = () => {
    if (done) return;
    done = true;
    window.location.reload();
  };
  navigator.serviceWorker.addEventListener('controllerchange', reload, { once: true });
  setTimeout(reload, 4000); // safety net: the new version is active by now in any case
  updateSW(false); // tells the waiting worker to take over (SKIP_WAITING)
  return true;
}

/** The player saw the "ready to play offline" notice: do not show it again. */
export function markOfflineReadySeen() {
  try {
    localStorage.setItem(OFFLINE_SEEN_KEY, '1');
  } catch {}
  setState({ offlineReady: false });
}

function watchForUpdates(reg) {
  let last = 0;
  const check = () => {
    if (navigator.onLine === false) return; // offline: nothing to fetch, try again when we are back
    if (reg.installing || state.updateReady) return;
    const now = Date.now();
    if (now - last < CHECK_MIN_GAP_MS) return;
    last = now;
    reg.update().catch(() => {}); // network hiccup: the next trigger retries
  };
  setInterval(check, CHECK_EVERY_MS);
  window.addEventListener('online', check);
  document.addEventListener('visibilitychange', () => {
    if (document.visibilityState === 'visible') check();
  });
}

async function removeServiceWorkers() {
  // Dev: make sure a service worker left over from a production build on this origin is gone (it would break HMR).
  const regs = await navigator.serviceWorker.getRegistrations();
  await Promise.all(regs.map((r) => r.unregister()));
}

/**
 * Call once at startup. Registers the service worker in production builds; in dev it removes any leftover one.
 * Never throws.
 */
export function initPWA() {
  if (initDone) return Promise.resolve();
  initDone = true;
  if (!hasWindow() || !('serviceWorker' in navigator) || window.isSecureContext === false) return Promise.resolve();
  if (!import.meta.env.PROD) return removeServiceWorkers().catch(() => {});

  const launchedAt = performance.now();
  let interacted = false;
  const touched = () => { interacted = true; };
  for (const t of ['pointerdown', 'keydown']) window.addEventListener(t, touched, { capture: true, once: true });
  const hadController = !!navigator.serviceWorker.controller;
  let reloadedForUpdate = false;
  try {
    reloadedForUpdate = sessionStorage.getItem(RELOAD_KEY) === '1';
    sessionStorage.removeItem(RELOAD_KEY);
  } catch {
    reloadedForUpdate = true; // no storage: never risk a reload loop
  }
  setState({ supported: true });

  return import('virtual:pwa-register')
    .then(({ registerSW }) => {
      updateSW = registerSW({
        immediate: true,
        onRegisteredSW(_url, reg) {
          if (reg) watchForUpdates(reg);
        },
        // A new version finished downloading in the background and is waiting.
        onNeedRefresh() {
          setState({ updateReady: true });
          // Found right at launch (downloaded during an earlier session): switch before the player does anything.
          if (hadController && !reloadedForUpdate && !interacted && performance.now() - launchedAt < LAUNCH_WINDOW_MS) applyUpdate();
        },
        // First install finished: every game file is cached, the game now works with no network.
        onOfflineReady() {
          let seen = false;
          try {
            seen = localStorage.getItem(OFFLINE_SEEN_KEY) === '1';
          } catch {}
          if (!seen) setState({ offlineReady: true });
        },
        onRegisterError() {},
      });
    })
    .catch(() => {});
}
